#!/usr/bin/env python3
"""Distance-matched Hi-C and guide-level random-effects meta-analysis."""

import csv
import math
import statistics


def normal_sf(z):
    return 0.5 * math.erfc(z / math.sqrt(2.0))


def two_sided_normal(z):
    return 2.0 * normal_sf(abs(z))


def read_hic(path):
    bg = []
    candidates = {}
    with open(path, newline="") as fh:
        for row in csv.DictReader(fh):
            counts = [int(row["count_rep1"]), int(row["count_rep2"]), int(row["count_rep3"])]
            d = float(row["distance_bp"])
            if row["set"].strip().lower() == "background":
                bg.append((d, counts))
            else:
                candidates[row["pair_id"]] = (d, counts)
    return bg, candidates


def local_poisson_high_p(bg, d, counts):
    # Use a fixed distance window and exact Poisson upper-tail p.
    window = 150000.0
    nearby = [vals for bd, vals in bg if abs(bd - d) <= window]
    if len(nearby) < 10:
        ordered = sorted(bg, key=lambda x: abs(x[0] - d))
        nearby = [vals for _, vals in ordered[:30]]
    bg_vals = [v for vals in nearby for v in vals]
    lam = statistics.mean(bg_vals)
    total = sum(counts)
    # P(X >= total), Poisson(lambda * 3)
    # series lower regularized gamma P(total, 3*lam)
    x = 3.0 * lam
    if total <= 0:
        return 1.0, lam, len(nearby)
    if x <= 0:
        return 0.0, lam, len(nearby)
    # regularized lower incomplete gamma P(a,x) by series
    a = float(total)
    term = 1.0 / a
    s = term
    for n in range(1, 1000):
        term *= x / (a + n)
        s += term
        if abs(term) < abs(s) * 1e-15:
            break
    p_lower = s * math.exp(-x + a * math.log(x) - math.lgamma(a))
    return max(0.0, min(1.0, 1.0 - p_lower)), lam, len(nearby)


def read_expr(path):
    data = {}
    with open(path, newline="") as fh:
        for row in csv.DictReader(fh):
            key = (row["pair_id"], row["guide_id"], row["condition"])
            data.setdefault(key, []).append(float(row["rna_count"]))
    return data


def log2fc_and_se(ctrl, pert):
    mc = statistics.mean(ctrl)
    mp = statistics.mean(pert)
    vc = statistics.variance(ctrl)
    vp = statistics.variance(pert)
    y = math.log2(mp / mc)
    var = (1.0 / (math.log(2) ** 2)) * (
        vp / (len(pert) * mp * mp) + vc / (len(ctrl) * mc * mc)
    )
    return y, math.sqrt(var)


def random_effects_meta(effects, ses):
    k = len(effects)
    if k == 1:
        z = effects[0] / ses[0]
        return effects[0], ses[0], two_sided_normal(z), 0.0
    w = [1.0 / (s * s) for s in ses]
    sw = sum(w)
    fixed = sum(wi * yi for wi, yi in zip(w, effects)) / sw
    q = sum(wi * (yi - fixed) ** 2 for wi, yi in zip(w, effects))

